{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE TEMP TABLE Inventory_Data_Base AS (select \'OVER ALL\' as Source, CAST(NULL as string) AS facility, DATETIME(TIMESTAMP(_airbyte_emitted_at), \'Asia/Kolkata\') DATA_FETCH_DATE, CAST(NULL as string) AS asin, Sku_Code as SKU, upper(Item_Name) as PRODUCTNAME, cast(Total_Inventory as INT64) Available_Quantity ,NULL as MODELNO ,NULL as PRODUCTUNIQUECODE ,UPPER(Item_Name) PRODUCT_NAME ,NULL as DESCRIPTION ,NULL IS_COMBO ,image IMAGEURL ,size SIZE ,Upper(BRAND) BRAND ,CAST(NULL as string) CATEGORY ,color COLOR ,NULL WIDTH ,NULL HEIGHT ,NULL LENGTH ,NULL WEIGHT ,NULL MRP ,NULL COST ,CAST(NULL as string) as LOCATION_KEY ,CAST(NULL as string) as ACCOUNTINGUNIT ,CAST(NULL as string) as RESERVEDINVENTORY ,CAST(Available__ATP_ as int64) AVAILABLEINVENTORY ,NULL as INVENTORYTHRESHOLD ,NULL as SELLINGPRICETHRESHOLD ,shelf ,CASE WHEN shelf LIKE \'BG%\' THEN \'B-Grade\' ELSE \'A-Grade\'END AS grade_type from `maplemonk.Plaeto_db_get_shelfwise_inventory` where upper(Sku_Code) in (select distinct upper(product_code) from maplemonk.unicommerce_plaeto_get_product_master where upper(category_code) in (\'SCHOOL_SHOES\',\'DEFAULT\')) qualify row_number() over (partition by facility,sku_Code,shelf,PRODUCT_NAME, DATE(TIMESTAMP(_airbyte_emitted_at), \'Asia/Kolkata\') order by DATETIME(TIMESTAMP(_airbyte_emitted_at), \'Asia/Kolkata\')) = 1) UNION ALL (SELECT \'AMAZON VENDOR\' AS Source, CAST(NULL AS string) AS facility, CAST(am.StartDate AS DATETIME) AS DATA_FETCH_DATE, am.asin AS asin, sm.skucode AS sku, CAST(NULL AS string) AS PRODUCTNAME, inv.Available_Quantity, NULL AS MODELNO, NULL AS PRODUCTUNIQUECODE, CAST(NULL AS string) AS PRODUCT_NAME, NULL AS DESCRIPTION, NULL AS IS_COMBO, CAST(NULL AS string) AS IMAGEURL, CAST(NULL AS string) AS SIZE, CAST(NULL AS string) AS BRAND, CAST(NULL AS string) AS CATEGORY, CAST(NULL AS string) AS COLOR, NULL AS WIDTH, NULL AS HEIGHT, NULL AS LENGTH, NULL AS WEIGHT, NULL AS MRP, NULL AS COST, CAST(NULL AS string) AS LOCATION_KEY, CAST(NULL AS string) AS ACCOUNTINGUNIT, CAST(NULL AS string) AS RESERVEDINVENTORY, inv.Available_Quantity AS AVAILABLEINVENTORY, NULL AS INVENTORYTHRESHOLD, NULL AS SELLINGPRICETHRESHOLD, CAST(NULL AS string) AS shelf, inv.grade_type FROM ( SELECT * FROM `maplemonk.Amazon_Vendor_Partner_GET_VENDOR_INVENTORY_REPORT` QUALIFY row_number() over (partition by Asin, StartDate order by StartDate) = 1 ) am LEFT JOIN ( SELECT * FROM ( SELECT marketplace_sku, master_sku as skucode, product_code, category_gender, product_name, category, row_number() over (partition by lower(replace(marketplace_sku,\' \',\'\')) order by 1) rw FROM plaeup-wh.maplemonk.Final_SKU_master where lower(marketplace) like \'%amazon%\' ) WHERE rw = 1 ) sm ON am.asin = sm.marketplace_sku CROSS JOIN UNNEST([ STRUCT(\'A-Grade\' AS grade_type, CAST(am.sellableOnHandInventoryUnits AS INT64) AS Available_Quantity), STRUCT(\'B-Grade\' AS grade_type, CAST(am.unsellableOnHandInventoryUnits AS INT64) AS Available_Quantity) ]) AS inv WHERE IFNULL(inv.Available_Quantity, 0) > 0 and upper(sm.skucode) in (select distinct upper(product_code) from maplemonk.unicommerce_plaeto_get_product_master where upper(category_code) in (\'SCHOOL_SHOES\',\'DEFAULT\'))) ; CREATE TEMP TABLE Inventory_Data AS SELECT cast(DATA_FETCH_DATE as date) DATA_FETCH_DATE, UPPER(Source) Source, SKU, PRODUCT_NAME, BRAND, GRADE_TYPE, SUM(IFNULL(AVAILABLEINVENTORY,0)) AS AVAILABLEINVENTORY FROM Inventory_Data_Base GROUP BY 1, 2, 3, 4,5,6; CREATE TEMP TABLE Sales_Data_Daily AS SELECT cast(order_date as date) Order_date, REPLACE(coalesce(commonsku, sku), \'\\'\', \'\') AS SKU, MAX(product_name) product_name, SUM(IFNULL(quantity, 0)) AS QUANTITY, SUM(IFNULL(returned_quantity, 0)) AS RETURNED_QUANTITY, SUM(IFNULL(SELLING_PRICE,0)) SELLING_PRICE FROM maplemonk.plaeup_wh_sales_consolidated where (not(lower(order_status) like any (\'%cancel%\',\'%return%\') or lower(FINAL_SHIPPING_STATUS) like any (\'%cancel%\',\'%return%\'))) and cast(order_date as date) < (select max(DATA_FETCH_DATE) from Inventory_Data) GROUP BY 1,2; CREATE TEMP TABLE PRE_Sales_DRR AS select UPPER(Source) Source ,ID.GRADE_TYPE ,cast(coalesce(order_date,DATA_FETCH_DATE) as date) as Date ,coalesce(ID.SKU,SD.SKU) as SKU ,ifnull(sd.QUANTITY,0) as Quantity ,ifnull(id.AVAILABLEINVENTORY,0) as Available_Inventory ,case when ifnull(id.AVAILABLEINVENTORY,0) > ifnull(sd.QUANTITY,0) then 1 else 0 end as drr_flag from Sales_Data_Daily sd full outer join Inventory_Data ID on cast(ID.DATA_FETCH_DATE as date) = cast(sd.order_date as date) and lower(id.SKU) = lower(sd.SKU) ; CREATE TEMP TABLE Final_DRR AS select UPPER(pd.Source) source ,pd.GRADE_TYPE ,pd.date ,pd.sku ,sum(case when pdr.drr_flag = 1 then pdr.Quantity else 0 end) as drr_quantity ,sum(pdr.drr_flag) as drr_days from PRE_Sales_DRR pd left join PRE_Sales_DRR pdr on pd.sku = pdr.sku and DATE_DIFF(pd.date, pdr.date, DAY) <= 30 and DATE_DIFF(pd.date, pdr.date, DAY) > 0 group by 1,2,3,4; CREATE TEMP TABLE Sales_Data_Max_Weekly AS WITH WeeklySales AS ( SELECT DATE_TRUNC(order_date, WEEK) AS week_Start, REPLACE(coalesce(commonsku, sku), \'\\'\', \'\') AS SKU, SUM(IFNULL(quantity, 0)) AS QUANTITY, SUM(IFNULL(returned_quantity, 0)) AS RETURNED_QUANTITY, SUM(IFNULL(SELLING_PRICE,0)) SELLING_PRICE FROM maplemonk.plaeup_wh_sales_consolidated WHERE DATE_DIFF(CURRENT_DATE(), order_date, DAY) <= 56 and not(lower(order_status) like any (\'%cancel%\',\'%return%\') or lower(FINAL_SHIPPING_STATUS) like any (\'%cancel%\',\'%return%\')) GROUP BY 1, 2 ) SELECT week_Start, SKU, QUANTITY, RETURNED_QUANTITY FROM ( SELECT week_Start, SKU, QUANTITY, RETURNED_QUANTITY, SELLING_PRICE, ROW_NUMBER() OVER (PARTITION BY SKU ORDER BY QUANTITY DESC) AS ranking FROM WeeklySales ) ranked_weekly_sales WHERE ranking = 1; CREATE TEMP TABLE Sales_Data_Min_Weekly AS WITH WeeklySales AS ( SELECT DATE_TRUNC(order_date, WEEK) AS week_Start, REPLACE(coalesce(commonsku, sku), \'\\'\', \'\') AS SKU, SUM(IFNULL(quantity, 0)) AS QUANTITY, SUM(IFNULL(returned_quantity, 0)) AS RETURNED_QUANTITY, SUM(IFNULL(SELLING_PRICE,0)) SELLING_PRICE FROM maplemonk.plaeup_wh_sales_consolidated WHERE DATE_DIFF(CURRENT_DATE(), order_date, DAY) <= 56 and not(lower(order_status) like any (\'%cancel%\',\'%return%\') or lower(FINAL_SHIPPING_STATUS) like any (\'%cancel%\',\'%return%\')) GROUP BY 1, 2 ) SELECT week_Start, SKU, QUANTITY, RETURNED_QUANTITY, SELLING_PRICE FROM ( SELECT week_Start, SKU, QUANTITY, RETURNED_QUANTITY, SELLING_PRICE, ROW_NUMBER() OVER (PARTITION BY SKU ORDER BY QUANTITY) AS ranking FROM WeeklySales ) ranked_weekly_sales WHERE ranking = 1; CREATE TEMP TABLE INVENTORY_FINAL AS SELECT UPPER(i.Source) AS Source, i.GRADE_TYPE, i.DATA_FETCH_DATE, EXTRACT(DAY FROM DATE_SUB(i.DATA_FETCH_DATE, INTERVAL 1 DAY)) AS mtd_Days, i.SKU, i.PRODUCT_NAME AS Product_Final_Name, MAX(IFNULL(i.AVAILABLEINVENTORY, 0)) AS Available_Inventory, MAX(IFNULL(SWMax.QUANTITY, 0)) AS Max_Weekly_Sales, MAX(IFNULL(SWMin.QUANTITY, 0)) AS Min_Weekly_Sales, SUM(CASE WHEN DATE_DIFF(i.DATA_FETCH_DATE, s.Order_date, DAY) BETWEEN 1 AND 56 THEN s.QUANTITY ELSE 0 END) AS Sold_Quantity_56_Days, SUM(CASE WHEN DATE_DIFF(i.DATA_FETCH_DATE, s.Order_date, DAY) BETWEEN 1 AND 56 THEN s.SELLING_PRICE ELSE 0 END) AS Selling_Price_56_Days, SUM(CASE WHEN DATE_DIFF(i.DATA_FETCH_DATE, s.Order_date, DAY) BETWEEN 1 AND 30 THEN s.QUANTITY ELSE 0 END) AS Sold_Quantity_30_Days, SUM(CASE WHEN DATE_DIFF(i.DATA_FETCH_DATE, s.Order_date, DAY) BETWEEN 1 AND 30 THEN s.SELLING_PRICE ELSE 0 END) AS Selling_Price_30_Days, SUM(CASE WHEN DATE_DIFF(i.DATA_FETCH_DATE, s.Order_date, DAY) BETWEEN 1 AND 14 THEN s.QUANTITY ELSE 0 END) AS Sold_Quantity_14_Days, SUM(CASE WHEN DATE_DIFF(i.DATA_FETCH_DATE, s.Order_date, DAY) BETWEEN 1 AND 14 THEN s.SELLING_PRICE ELSE 0 END) AS Selling_Price_14_Days, SUM(CASE WHEN DATE_DIFF(i.DATA_FETCH_DATE, s.Order_date, DAY) BETWEEN 1 AND 7 THEN s.QUANTITY ELSE 0 END) AS Sold_Quantity_7_Days, SUM(CASE WHEN DATE_DIFF(i.DATA_FETCH_DATE, s.Order_date, DAY) BETWEEN 1 AND 7 THEN s.SELLING_PRICE ELSE 0 END) AS Selling_Price_7_Days, SUM(CASE WHEN DATE_DIFF(i.DATA_FETCH_DATE, s.Order_date, DAY) = 1 THEN s.QUANTITY ELSE 0 END) AS Sold_Quantity_last_day, SUM(CASE WHEN DATE_DIFF(i.DATA_FETCH_DATE, s.Order_date, DAY) = 1 THEN s.SELLING_PRICE ELSE 0 END) AS Selling_Price_last_day, SUM(CASE WHEN DATE_TRUNC(DATE_SUB(s.Order_date, INTERVAL 1 DAY), MONTH) = DATE_TRUNC(i.DATA_FETCH_DATE, MONTH) AND s.Order_date < i.DATA_FETCH_DATE THEN s.QUANTITY ELSE 0 END) AS sold_quantity_mtd, SUM(CASE WHEN DATE_TRUNC(DATE_SUB(s.Order_date, INTERVAL 1 DAY), MONTH) = DATE_TRUNC(i.DATA_FETCH_DATE, MONTH) AND s.Order_date < i.DATA_FETCH_DATE THEN s.SELLING_PRICE ELSE 0 END) AS Selling_Price_mtd FROM Inventory_Data i LEFT JOIN Sales_Data_Daily s ON i.SKU = s.SKU AND s.Order_date >= DATE_SUB(i.DATA_FETCH_DATE, INTERVAL 56 DAY) AND s.Order_date < i.DATA_FETCH_DATE LEFT JOIN Sales_Data_Max_Weekly SWMax ON i.SKU = SWMax.SKU LEFT JOIN Sales_Data_Min_Weekly SWMin ON i.SKU = SWMin.SKU GROUP BY 1, 2, 3, 4, 5, 6; CREATE OR REPLACE TABLE MAPLEMONK.Plaeto_INVENTORY_FACT_ITEMS AS SELECT COALESCE(IFT.source, fD.Source) Source ,IFT.GRADE_TYPE ,IFT.DATA_FETCH_DATE ,IFT.mtd_Days ,IFT.SKU ,sm.style_code ,sm.colour_code ,sm.Category_Gender ,sm.Product_Code ,sm.Style_Name ,sm.Sub_Style_Name ,sm.size ,sm.colour ,sm.outsole_colour ,sm.product_name ,sm.Colour_2 ,sm.Category ,coalesce(IFT.Product_Final_Name) Product_Final_Name ,cast(null as string) SUB_CATEGORY ,IFT.Available_Inventory ,IFT.Max_Weekly_Sales ,IFT.Min_Weekly_Sales ,IFT.Sold_Quantity_56_Days ,IFT.Selling_Price_56_Days ,IFT.Sold_Quantity_30_Days ,IFT.Selling_Price_30_Days ,IFT.Sold_Quantity_14_Days ,IFT.Selling_Price_14_Days ,IFT.Sold_Quantity_7_Days ,IFT.Selling_Price_7_Days ,IFT.sold_quantity_mtd ,IFT.Selling_Price_mtd ,IFT.Sold_Quantity_last_day ,IFT.Selling_Price_last_day ,FD.drr_quantity ,FD.drr_days FROM INVENTORY_FINAL IFT LEFT JOIN Final_DRR FD ON CAST(ift.DATA_FETCH_DATE AS DATE) = CAST(fd.date AS DATE) AND LOWER(ift.sku) = LOWER(fd.sku) AND UPPER(ift.source) = UPPER(fd.source) AND ift.GRADE_TYPE = fd.GRADE_TYPE LEFT JOIN (select * from plaeup-wh.maplemonk.Final_SKU_master qualify row_number() over (partition by master_sku order by 1) = 1 ) sm on lower(sm.master_sku) = lower(ift.sku) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            